 private record Manifest(Path root,long epoch,Properties properties){}
 private record Source(Path root,WeakReference<PackBind> stock,WeakReference<PackModel> base,PackedModelGeometry.Mesh geometry,long epoch){}
 private static volatile Manifest manifest;private static volatile Source source;private static long sourceEpoch;
 private static final ThreadPoolExecutor preflight=new ThreadPoolExecutor(0,1,10,TimeUnit.SECONDS,new ArrayBlockingQueue<>(1),job->{var thread=new Thread(job,"PZVR optional pack preflight");thread.setDaemon(true);return thread;},new ThreadPoolExecutor.DiscardOldestPolicy());
